set -euo pipefail

usage() {
    echo "usage: $0 --meryl M --lookup L --python P --scripts DIR --mode trio --k K --threads N --out DIR --unitigs FASTA [--color-fraction F] [--color-minimum N] [--child FILE] [--maternal FILE] [--paternal FILE]" >&2
    exit 1
}

MERYL=""
LOOKUP=""
PYTHON=python3
SCRIPTS=""
MODE=""
K=31
THREADS=1
OUT=""
UNITIGS=""
COLOR_FRACTION=0.9
COLOR_MINIMUM=100
CHILD=()
MATERNAL=()
PATERNAL=()

while [[ $# -gt 0 ]]; do
    case "$1" in
        --meryl) MERYL=$2; shift 2 ;;
        --lookup) LOOKUP=$2; shift 2 ;;
        --python) PYTHON=$2; shift 2 ;;
        --scripts) SCRIPTS=$2; shift 2 ;;
        --mode) MODE=$2; shift 2 ;;
        --k) K=$2; shift 2 ;;
        --threads) THREADS=$2; shift 2 ;;
        --out) OUT=$2; shift 2 ;;
        --unitigs) UNITIGS=$2; shift 2 ;;
        --color-fraction) COLOR_FRACTION=$2; shift 2 ;;
        --color-minimum) COLOR_MINIMUM=$2; shift 2 ;;
        --child) CHILD+=("$2"); shift 2 ;;
        --maternal) MATERNAL+=("$2"); shift 2 ;;
        --paternal) PATERNAL+=("$2"); shift 2 ;;
        *) usage ;;
    esac
done

[[ -n "$MERYL" && -n "$LOOKUP" && -n "$SCRIPTS" && -n "$OUT" && -n "$UNITIGS" ]] || usage
[[ -n "$PYTHON" ]] || PYTHON=python3
[[ "$MODE" == trio ]] || usage
[[ ${#CHILD[@]} -gt 0 ]] || usage
[[ ${#MATERNAL[@]} -gt 0 && ${#PATERNAL[@]} -gt 0 ]] || usage

mkdir -p "$OUT"

count_db() {
    # All read sets use the same regular-space k so marker databases remain
    # comparable and can be intersected directly.
    local name=$1
    shift
    "$MERYL" count k="$K" threads="$THREADS" "$@" output "$OUT/$name.meryl"
    "$MERYL" ploidy "$OUT/$name.meryl" > "$OUT/$name.ploidy.tsv"
}

cutoff() {
    # Round the continuous trough to the nearest integer; greater-than below
    # retains counts strictly above that boundary.
    awk '$1 == "noise-trough" { print int($2 + 0.5); exit }' "$1"
}

solid_db() {
    local input=$1
    local threshold=$2
    local output=$3
    "$MERYL" greater-than "$threshold" "$input" output "$output"
}

distinct_count() {
    "$MERYL" statistics "$1" | awk '$1 == "distinct" { print $2; exit }'
}

count_db child "${CHILD[@]}"
CHILD_CUTOFF=0

if [[ ${#MATERNAL[@]} -gt 0 ]]; then
    count_db maternal "${MATERNAL[@]}"
    MAT_CUTOFF=$(cutoff "$OUT/maternal.ploidy.tsv")
fi
if [[ ${#PATERNAL[@]} -gt 0 ]]; then
    count_db paternal "${PATERNAL[@]}"
    PAT_CUTOFF=$(cutoff "$OUT/paternal.ploidy.tsv")
fi

if [[ "$MODE" == trio ]]; then
    # Follow Merqury hapmers.sh/diff.sh/filt.sh ordering.  First filter each
    # parent-specific set using its own trough.  Intersect child first so the
    # inherited databases retain child multiplicities, then filter those using
    # their own independently estimated troughs.
    "$MERYL" difference "$OUT/maternal.meryl" "$OUT/paternal.meryl" output "$OUT/maternal.only.raw.meryl"
    "$MERYL" difference "$OUT/paternal.meryl" "$OUT/maternal.meryl" output "$OUT/paternal.only.raw.meryl"
    "$MERYL" ploidy "$OUT/maternal.only.raw.meryl" > "$OUT/maternal.only.ploidy.tsv"
    "$MERYL" ploidy "$OUT/paternal.only.raw.meryl" > "$OUT/paternal.only.ploidy.tsv"
    MAT_ONLY_CUTOFF=$(cutoff "$OUT/maternal.only.ploidy.tsv")
    PAT_ONLY_CUTOFF=$(cutoff "$OUT/paternal.only.ploidy.tsv")
    solid_db "$OUT/maternal.only.raw.meryl" "$MAT_ONLY_CUTOFF" "$OUT/maternal.auto.only.meryl"
    solid_db "$OUT/paternal.only.raw.meryl" "$PAT_ONLY_CUTOFF" "$OUT/paternal.auto.only.meryl"
    solid_db "$OUT/maternal.only.raw.meryl" 2 "$OUT/maternal.cutoff2.only.meryl"
    solid_db "$OUT/paternal.only.raw.meryl" 2 "$OUT/paternal.cutoff2.only.meryl"

    for candidate in auto cutoff2; do
        "$MERYL" intersect "$OUT/child.meryl" "$OUT/maternal.$candidate.only.meryl" output "$OUT/maternal.$candidate.inherited.raw.meryl"
        "$MERYL" intersect "$OUT/child.meryl" "$OUT/paternal.$candidate.only.meryl" output "$OUT/paternal.$candidate.inherited.raw.meryl"
    done

    "$MERYL" ploidy "$OUT/maternal.auto.inherited.raw.meryl" > "$OUT/maternal.inherited.ploidy.tsv"
    "$MERYL" ploidy "$OUT/paternal.auto.inherited.raw.meryl" > "$OUT/paternal.inherited.ploidy.tsv"
    MAT_CUTOFF=$(cutoff "$OUT/maternal.inherited.ploidy.tsv")
    PAT_CUTOFF=$(cutoff "$OUT/paternal.inherited.ploidy.tsv")
    solid_db "$OUT/maternal.auto.inherited.raw.meryl" "$MAT_CUTOFF" "$OUT/maternal.auto.inherited.meryl"
    solid_db "$OUT/paternal.auto.inherited.raw.meryl" "$PAT_CUTOFF" "$OUT/paternal.auto.inherited.meryl"
    solid_db "$OUT/maternal.cutoff2.inherited.raw.meryl" 2 "$OUT/maternal.cutoff2.inherited.meryl"
    solid_db "$OUT/paternal.cutoff2.inherited.raw.meryl" 2 "$OUT/paternal.cutoff2.inherited.meryl"

    {
        printf 'candidate\tmaternal\tpaternal\n'
        printf 'auto\t%s\t%s\n' "$(distinct_count "$OUT/maternal.auto.inherited.meryl")" "$(distinct_count "$OUT/paternal.auto.inherited.meryl")"
        printf 'cutoff2\t%s\t%s\n' "$(distinct_count "$OUT/maternal.cutoff2.inherited.meryl")" "$(distinct_count "$OUT/paternal.cutoff2.inherited.meryl")"
    } > "$OUT/marker_counts.tsv"

    "$PYTHON" "$SCRIPTS/select_marker_cutoffs.py" \
        --maternal-ploidy "$OUT/maternal.inherited.ploidy.tsv" \
        --paternal-ploidy "$OUT/paternal.inherited.ploidy.tsv" \
        --marker-counts "$OUT/marker_counts.tsv" \
        --output "$OUT/marker_qc.tsv"
    SELECTED=$(awk '$1 == "selection" { print $2 }' "$OUT/marker_qc.tsv")
    # Parental specificity and inheritance are properties of the read sets;
    # assembly copy number is a separate final filter.  Requiring exactly one
    # occurrence across all non-HPC unitigs excludes repeated k-mers, including
    # k-mers duplicated across overlapping node ends, before lookup.
    "$MERYL" count k="$K" threads="$THREADS" "$UNITIGS" output "$OUT/assembly.meryl"
    "$MERYL" equal-to 1 "$OUT/assembly.meryl" output "$OUT/assembly.single-copy.meryl"
    "$MERYL" intersect \
        "$OUT/paternal.$SELECTED.inherited.meryl" "$OUT/assembly.single-copy.meryl" \
        output "$OUT/paternal.$SELECTED.inherited.single-copy.meryl"
    "$MERYL" intersect \
        "$OUT/maternal.$SELECTED.inherited.meryl" "$OUT/assembly.single-copy.meryl" \
        output "$OUT/maternal.$SELECTED.inherited.single-copy.meryl"

    # Rukki's trio schema is maternal then paternal. Preserve that biological
    # order here; the workflow maps paternal paths to final haplotype 1 later.
    # Preserve the raw lookup for diagnostics, then apply the configured
    # marker-count thresholds.
    "$LOOKUP" -existence -threads "$THREADS" \
        -mers "$OUT/maternal.$SELECTED.inherited.single-copy.meryl" "$OUT/paternal.$SELECTED.inherited.single-copy.meryl" \
        -sequence "$UNITIGS" \
      > "$OUT/trio.lookup.tsv"
    "$PYTHON" "$SCRIPTS/color_parental_markers.py" \
        --lookup "$OUT/trio.lookup.tsv" --output "$OUT/parental.colors.csv" \
        --fraction "$COLOR_FRACTION" --minimum-total "$COLOR_MINIMUM"
fi

touch "$OUT/markers.finished"
